def fifo_cogs(layers: Sequence[Tuple[int, int, int]], qty: int) -> Tuple[int, List[Tuple[int, int, int]]]:
    """
    Cost of goods sold for a shipment, using FIFO cost layers.
    """
    if qty < 0:
        raise ValueError("qty < 0")
    if qty > 0 and not layers:
        raise ValueError("no layers")

    # Sort layers: oldest receipt_day first, then original index for same day
    indexed = []
    for i, (day, l_qty, cost) in enumerate(layers):
        indexed.append({'day': day, 'qty': l_qty, 'cost': cost, 'idx': i})

    sorted_layers = sorted(indexed, key=lambda x: (x['day'], x['idx']))

    total_cost = 0
    rem_qty = qty
    rem_layers = []

    for layer in sorted_layers:
        if rem_qty > 0:
            if layer['qty'] <= rem_qty:
                total_cost += layer['qty'] * layer['cost']
                rem_qty -= layer['qty']
            else:
                total_cost += rem_qty * layer['cost']
                leftover = layer['qty'] - rem_qty
                rem_layers.append((layer['day'], leftover, layer['cost']))
                rem_qty = 0
        else:
            rem_layers.append((layer['day'], layer['qty'], layer['cost']))

    if rem_qty > 0:
        # Shortfall: costed at the unit cost of the most recent receipt
        last_layer_cost = sorted_layers[-1]['cost']
        total_cost += rem_qty * last_layer_cost

    return total_cost, rem_layers
